    "paketTitle": "TOEFL Listening Comprehension #1",
    "audioScript": "Woman: Do you mind if I open the window? It’s getting stuffy in here. Man: Go right ahead—some fresh air would do us both good.",
    "soal": "[Listening Comprehension]\nKlik tombol **Putar Audio** di bawah untuk mendengarkan percakapan/rekaman, lalu jawab pertanyaannya:\n\n**Question:** How does the man respond to the woman’s request?",
