    "audioScript": "Narrator: Listen to a conversation between two students about a geology field trip. Man: Are you packed for Saturday’s fossil hunt at Cedar Ridge? Woman: Almost, except I still need sturdy hiking boots. Do you think regular sneakers will hold up on the shale slopes? Man: Honestly, the loose rock gets pretty slippery after rain. You can borrow a pair from the outing club for free if you stop by before five.",
