    "id": "toefl_lis_2_19",
    "kategori": "TOEFL",
    "subKategori": "Listening Comprehension",
    "paketNo": 2,
    "paketTitle": "TOEFL Listening Comprehension #2",
    "audioScript": "Man: Is Professor Wright’s office hours session still at three today? Woman: She posted a note moving it to four because of a faculty meeting.",
    "soal": "[Listening Comprehension]\nKlik tombol **Putar Audio** di bawah untuk mendengarkan percakapan/rekaman, lalu jawab pertanyaannya:\n\n**Question:** When will Professor Wright hold office hours today?",
