    "paketNo": 3,
    "paketTitle": "TOEFL Listening Comprehension #3",
    "audioScript": "Man: Did you hear that the city is adding protected bike lanes along Oak Avenue? Woman: Finally! Riding there during rush hour was nerve-racking.",
