    "paketTitle": "TOEFL Listening Comprehension #3",
    "audioScript": "Man: Are the museum’s fossil casts real bones or replicas? Woman: Most on display are resin casts, while the fragile originals stay in climate-controlled vaults.",
    "soal": "[Listening Comprehension]\nKlik tombol **Putar Audio** di bawah untuk mendengarkan percakapan/rekaman, lalu jawab pertanyaannya:\n\n**Question:** Where are the original fossils kept?",
