    "paketTitle": "TOEFL Listening Comprehension #3",
    "audioScript": "Narrator: Listen to a career center workshop clip. When preparing for a behavioral job interview, avoid vague one-word answers. Instead, structure your response using the STAR method: briefly describe the Situation, explain your Task, detail the Action you took, and conclude with the measurable Result.",
    "soal": "[Listening Comprehension]\nKlik tombol **Putar Audio** di bawah untuk mendengarkan percakapan/rekaman, lalu jawab pertanyaannya:\n\n**Question:** In the STAR method, what does the letter \"R\" stand for?",
