    "paketTitle": "TOEFL Listening Comprehension #4",
    "audioScript": "Narrator: Listen to a student speaking with a financial aid advisor. Woman: I received a notice that my work-study hours were capped at twelve per week this term. Man: Yes, federal rules limit part-time campus jobs during heavy course loads so academics come first. However, during winter break you can work up to thirty hours a week.",
    "soal": "[Listening Comprehension]\nKlik tombol **Putar Audio** di bawah untuk mendengarkan percakapan/rekaman, lalu jawab pertanyaannya:\n\n**Question:** Why are work-study hours capped at twelve during the term?",
