    "pembahasan": "Identifikasi Pola (Inversi Negatif):: Perhatikan penanda waktu, posisi koma, dan kesesuaian subjek-predikat.\nAnalisis Jawaban:: Ungkapan negatif di awal (\"Not until...\") memicu inversi pada klausa utama: did + subjek + V1.\nKesimpulan:: Pilihan yang tepat adalah C (**did the board realize**)."
