    "paketTitle": "TOEFL Reading Comprehension #1",
    "soal": "**Passage: Urban Heat Islands**\nLarge metropolitan areas frequently record daytime temperatures several degrees higher than surrounding rural landscapes, a phenomenon known as the urban heat island effect. Dark asphalt roads, dense concrete buildings, and reduced vegetation absorb solar radiation throughout the afternoon and release heat slowly after sunset. Consequently, nighttime cooling is sharply curtailed, increasing summer electricity demand for air conditioning. Municipal planners have begun countering this trend by planting street trees, installing reflective cool roofs, and expanding permeable pavements that retain moisture and cool nearby air through evaporation. Studies in several cities show that combining tree canopy expansion with high-albedo roofing can lower peak neighborhood air temperatures by two to three degrees Celsius during heatwaves.\n\n**Question:** It can be inferred from the passage that expanding urban vegetation would most likely...",
