    "paketTitle": "TOEFL Reading Comprehension #1",
    "soal": "**Passage: Mycorrhizal Fungi Networks**\nBeneath the floor of a temperate forest, tree roots rarely operate in isolation. Most form symbiotic partnerships with mycorrhizal fungi, whose microscopic filaments weave through soil pores far beyond the reach of roots alone. In exchange for sugars produced through photosynthesis, the fungi supply trees with phosphorus, nitrogen, and water. Recent field experiments indicate that connected trees can even transfer carbon compounds through these underground fungal threads, helping shaded seedlings survive until gaps open in the forest canopy. Ecologists sometimes compare this underground web to a biological marketplace where resources flow from surplus areas to stressed trees.\n\n**Question:** The word \"microscopic\" in the second sentence means...",
