    "paketTitle": "TOEFL Reading Comprehension #1",
    "soal": "**Passage: Chronometers and Longitude**\nFor centuries, sailors could determine their latitude by measuring the angle of the Sun or North Star above the horizon, yet calculating longitude—east-west position—remained perilously inaccurate on long voyages. Because Earth rotates fifteen degrees every hour, knowing precise time at a reference port allows navigators to compare it with local solar noon and deduce longitude. Early pendulum clocks failed at sea due to rolling waves and temperature swings. In the eighteenth century, clockmaker John Harrison solved this challenge by inventing the marine chronometer, a spring-driven timepiece insulated against motion and climate, drastically reducing shipwrecks and transforming global maritime charts.\n\n**Question:** Why was determining longitude difficult before the eighteenth century?",
