    "pembahasan": "Strategi Scanning:: Cari kata kunci pertanyaan (\"Why was determining longitude difficult before...\") di wacana **Chronometers and Longitude**.\nPembuktian Teks:: Menentukan bujur butuh jam presisi di laut, sementara teknologi saat itu belum memadai.\nKesimpulan:: Jawaban yang tepat adalah opsi A."
