    "soal": "**Passage: The Invention of Movable Type**\nLong before Johannes Gutenberg assembled his famous printing press in Mainz around 1450, artisans in East Asia had pioneered movable type printing. In eleventh-century China, inventor Bi Sheng carved individual characters from baked clay, arranging them in iron frames coated with resin so the blocks could be reused for new texts. Later, Korean craftsmen cast durable metal type sets during the Goryeo dynasty, producing preserved volumes such as the Jikji in 1377. While East Asian languages with thousands of distinct characters made hand-setting labor-intensive, the concept of reusable type laid crucial groundwork for the global spread of printed knowledge.\n\n**Question:** Why were Bi Sheng’s iron frames coated with resin?",
