    "soal": "**Passage: Acoustic Ecology of Whales**\nBecause light penetrates poorly underwater, whales and dolphins rely heavily on sound to navigate, locate food, and maintain social bonds across vast ocean basins. Baleen whales emit low-frequency calls that can travel hundreds of kilometers through deep sound channels. However, rising commercial shipping traffic has steadily elevated ambient ocean noise over the past fifty years, overlapping directly with the frequencies whales use. Marine biologists warn that this acoustic smog masks vital communication, forcing some whale populations to alter their vocal pitch or abandon traditional feeding grounds. In response, several port authorities have tested voluntary vessel slowdown corridors, finding that modest speed reductions cut underwater propeller noise substantially.\n\n**Question:** The word \"substantially\" in the final sentence is closest in meaning to...",
