    "soal": "**Passage: Behavioral Economics and Nudges**\nClassical economic theory assumes that individuals weigh every option rationally to maximize personal benefit. Behavioral economists, however, observe that human choices are routinely shaped by limited attention, inertia, and how options are presented. A subtle shift in presentation—called a \"nudge\"—can guide better outcomes without forbidding any alternative. For example, automatically enrolling new employees in retirement savings plans while allowing them to opt out raises participation dramatically compared to requiring active sign-up forms, even though the financial rules remain identical. Policymakers now apply similar choice architecture to encourage energy conservation, organ donation, and timely tax filing.\n\n**Question:** What distinguishes behavioral economics from classical economic theory?",
