    "paketTitle": "TOEFL Reading Comprehension #2",
    "soal": "**Passage: Exoplanets and the Transit Method**\nDetecting planets orbiting distant stars is extraordinarily challenging because stars shine billions of times brighter than the worlds circling them. Rather than photographing exoplanets directly, astronomers frequently rely on the transit method. When an orbiting planet passes directly between its host star and an observer’s telescope, it blocks a tiny fraction of starlight, producing a periodic, measurable dip in brightness. By timing these recurring dips and measuring their depth, scientists can calculate both the planet’s orbital period and its approximate diameter. Space observatories such as Kepler and TESS have used this technique to confirm thousands of worlds beyond our solar system.\n\n**Question:** What happens during a planetary transit?",
