    "pembahasan": "Strategi Scanning:: Cari kata kunci pertanyaan (\"What happens during a planetary transit?...\") di wacana **Exoplanets and the Transit Method**.\nPembuktian Teks:: Planet melintas di antara bintang dan pengamat sehingga meredupkan sedikit cahaya bintang.\nKesimpulan:: Jawaban yang tepat adalah opsi D."
