    "paketTitle": "TOEFL Reading Comprehension #3",
    "soal": "**Passage: The History of Salt Taxation**\nLong before modern refrigeration, salt was indispensable for preserving meat, fish, and dairy across seasons, making it a strategic commodity comparable to oil today. Because salt deposits and coastal evaporation pans were concentrated in specific locations, rulers throughout history found them remarkably easy to monitor and tax. In ancient China, imperial salt monopolies funded monumental public works and frontier defenses, while in eighteenth-century France, the hated gabelle salt tax forced citizens to purchase fixed quotas at inflated prices, fueling widespread resentment prior to the French Revolution.\n\n**Question:** What is the main idea of the passage?",
