    "soal": "**Passage: Vertical Farming in Cities**\nTraditional open-field agriculture consumes roughly seventy percent of global freshwater withdrawals and remains vulnerable to droughts, floods, and long supply chains. In response, some urban entrepreneurs have turned to vertical farming—growing leafy greens and herbs indoors in stacked hydroponic or aeroponic trays illuminated by tuned LED lights. By recirculating nutrient-rich water in closed loops, vertical farms use up to ninety-five percent less water than conventional fields and require zero chemical pesticides. However, high electricity costs for artificial lighting and climate control currently limit most commercial vertical farms to fast-growing, high-margin crops rather than staple grains like wheat or rice.\n\n**Question:** What is the primary obstacle preventing vertical farms from growing staple grains?",
