    "paketTitle": "TOEFL Reading Comprehension #3",
    "soal": "**Passage: The Rosetta Stone**\nFor over a thousand years after the fall of ancient Egypt, the meaning of Egyptian hieroglyphs remained unreadable to scholars, who mistakenly assumed the symbols were purely mystical pictures rather than phonetic signs. In 1799, French soldiers digging fortifications near Rashid (Rosetta) uncovered a dark granodiorite slab inscribed with a single royal decree written in three scripts: formal hieroglyphs, everyday Egyptian demotic, and ancient Greek. Because scholars already understood ancient Greek, the Rosetta Stone provided the crucial bilingual key. Comparing royal names enclosed in oval cartouches, French philologist Jean-François Champollion cracked the phonetic system in 1822, unlocking three millennia of Egyptian history.\n\n**Question:** What does \"who\" in \"who mistakenly assumed\" refer to?",
