    "paketTitle": "TOEFL Reading Comprehension #4",
    "soal": "**Passage: Tree Rings and Dendrochronology**\nEvery growing season, temperate trees add a new concentric layer of wood beneath their bark, forming rings whose thickness reflects annual environmental conditions. In wet, mild years, trees produce wide rings, whereas severe droughts or cold snaps leave narrow, densely packed bands. By matching overlapping ring-width patterns from living trees, historic timber beams, and preserved subfossil logs, scientists known as dendrochronologists have built continuous climate chronologies stretching back more than ten thousand years. These wooden archives allow researchers not only to date ancient wooden structures to the exact calendar year, but also to reconstruct past droughts long before modern weather instruments existed.\n\n**Question:** What is the primary subject of the passage?",
