    "paketTitle": "TOEFL Reading Comprehension #4",
    "soal": "**Passage: The Invention of Pasteurization**\nIn mid-nineteenth-century France, winemakers and brewers suffered heavy financial losses when bottled beverages unexpectedly soured during storage or shipping. At the time, many chemists insisted that spoilage was a purely chemical breakdown requiring no living agents. French microbiologist Louis Pasteur examined spoiled samples under a microscope and discovered rod-shaped bacteria alongside beneficial yeast cells. He demonstrated that heating liquids briefly to roughly sixty degrees Celsius—hot enough to destroy harmful microbes without boiling away flavor—kept wine, beer, and later milk safe for weeks, establishing the germ theory of spoilage and modern food safety.\n\n**Question:** What problem prompted Louis Pasteur’s investigation?",
