    "soal": "**Passage: Tidally Locked Exoplanets**\nMany rocky planets discovered around small, dim red dwarf stars orbit so closely to their suns that gravitational forces lock their rotation. Like Earth’s Moon, these \"tidally locked\" worlds always keep the same hemisphere facing their star in eternal daylight while the opposite side endures perpetual night. Early climate models predicted that any atmosphere on such a planet would freeze solid on the dark side, leaving the world barren. More recent three-dimensional simulations, however, reveal that brisk winds and ocean currents could circulate heat across the twilight zone—the ring between day and night—potentially sustaining liquid water and temperate habitats.\n\n**Question:** What is the main topic of the passage?",
