    "paketTitle": "TOEFL Reading Comprehension #4",
    "soal": "**Passage: Beavers as Ecosystem Engineers**\nFew animals reshape their surroundings as dramatically as the North American beaver. Using chisel-like front teeth, beavers fell saplings and weave mud, stones, and branches into sturdy dams across small streams. Behind each dam, rushing water slows into a tranquil pond that traps sediment, recharges groundwater aquifers, and stores moisture through dry summers. These newly created wetlands attract amphibians, waterfowl, and juvenile salmon seeking shelter from swift currents. Even after beavers abandon a site, the nutrient-rich silt left behind fosters lush meadows, earning beavers the title \"ecosystem engineers.\"\n\n**Question:** Why are beavers called \"ecosystem engineers\"?",
